@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}h2{margin:0 0 70px;font-size:104px;line-height:.95;letter-spacing:-.045em;font-weight:var(--rf-heading-weight)}
.fg{display:grid;grid-template-columns:1fr 1fr;gap:28px}
.tile{display:flex;flex-direction:column;gap:22px;padding:44px 40px;min-height:380px;border-radius:40px;background:var(--rf-surface);border:2px solid color-mix(in srgb,var(--rf-text) 8%,transparent);animation:tl .9s cubic-bezier(.16,1,.3,1) both}
